add('kostra','Kostra','anatomie-kostra.webp','Kosti tvoří oporu těla, chrání orgány a spolu se svaly umožňují pohyb. Vyber kost nebo skupinu kostí a prozkoumej její úlohu.','Pohled zepředu v anatomickém postavení s dlaněmi dopředu. Pravá strana těla je vlevo. Některé drobné kosti jsou pro přehlednost sdružené; nejde o soupis všech kostí.',[
bone('kost_lebka','Lebka','Cranium','Pevný obal mozku a kostěný základ obličeje.','Na hlavě; tvoří ji mozková a obličejová část.','Chrání mozek a vytváří oporu smyslových orgánů.','S páteří ji spojuje první krční obratel. Dolní čelist umožňuje žvýkání.','Lebka není jediná kost. Většinu jejích kostí spojují pevné švy.',[493,67],[65,70],['M510 18 C450 14 433 47 443 103 L457 137 L464 177 Q510 215 551 178 L560 138 L575 101 C584 44 554 13 510 18 Z']),
bone('kost_klicni','Klíční kosti','Claviculae','Vzpěry mezi hrudníkem a rameny.','V horní části hrudníku mezi hrudní kostí a lopatkami.','Udržují ramena od hrudníku a přenášejí síly z horních končetin.','S lopatkami tvoří pletenec horní končetiny.','Klíční kost je hmatná těsně pod kůží.',[410,265],[45,230],['M342 253 Q362 252 398 258 L484 262 L491 272 Q469 279 433 272 L367 267 L340 272 Z'],{mirroredPaths:['M342 253 Q362 252 398 258 L484 262 L491 272 Q469 279 433 272 L367 267 L340 272 Z']}),
bone('kost_hrudni','Hrudní kost','Sternum','Plochá kost uprostřed přední stěny hrudníku.','Ve střední čáře mezi pravými a levými žebry.','Spolu se žebry chrání srdce a plíce.','Připojují se k ní klíční kosti a chrupavky horních žeber.','Dolní konec tvoří mečovitý výběžek.',[510,340],[755,310],['M488 273 L535 273 L530 307 L526 320 L527 381 L519 401 L516 427 L505 429 L499 403 L492 384 L492 317 L486 306 Z']),
bone('kost_zebra','Žebra','Costae','Pružný kostěný rám hrudníku.','Po stranách hrudníku; vzadu se připojují k hrudním obratlům.','Chrání hrudní orgány a účastní se dýchacích pohybů.','Vpředu jsou mnohá spojena s hrudní kostí pomocí chrupavek.','Člověk obvykle má 12 párů žeber. Poslední dva páry vpředu volně končí.',[415,389],[40,390],['M436 271 C404 288 390 329 386 372 L385 432 Q386 486 412 536 L423 522 L420 501 L439 480 L461 469 L480 457 L489 430 L484 397 L487 371 L487 320 C453 317 425 299 436 271 Z'],{mirroredPaths:['M436 271 C404 288 390 329 386 372 L385 432 Q386 486 412 536 L423 522 L420 501 L439 480 L461 469 L480 457 L489 430 L484 397 L487 371 L487 320 C453 317 425 299 436 271 Z']}),
bone('kost_pater','Páteř','Columna vertebralis','Ohebná osa a opora trupu.','Od spodiny lebky po pánev. Hrudní část je zde částečně zakrytá žebry.','Nese trup a chrání míchu v páteřním kanálu.','Skládá se z obratlů; mezi většinou sousedních těl jsou meziobratlové ploténky.','Páteř není rovná tyč. Při pohledu z boku má přirozená zakřivení.',[510,552],[755,520],['M489 195 L535 195 L532 229 L544 244 L535 261 L486 260 L481 244 L490 228 Z','M490 431 L531 431 L539 465 L537 498 L549 530 L540 548 L552 582 L538 598 L533 622 L488 622 L480 597 L468 583 L478 552 L468 529 L481 497 L479 461 Z']),
bone('kost_panev','Pánev','Pelvis','Kostěný prstenec spojující trup s dolními končetinami.','V dolní části trupu.','Přenáší hmotnost těla na nohy a chrání pánevní orgány.','Tvoří ji pánevní kosti, křížová kost a kostrč. Kloubní jamky přijímají hlavice stehenních kostí.','Pánevní kost vzniká srůstem kosti kyčelní, sedací a stydké.',[420,631],[60,620],['M394 590 Q430 574 454 597 L466 626 L488 629 L533 629 L558 623 Q569 575 617 588 C650 600 638 642 619 664 L614 707 L589 735 Q581 777 545 779 L513 754 L480 780 Q446 780 428 751 L406 717 L403 677 C386 648 369 610 394 590 Z']),
bone('kost_pazni','Pažní kosti','Humeri','Dlouhé kosti paží.','Mezi ramenem a loktem.','Slouží jako páky pro pohyb horních končetin.','S lopatkou tvoří ramenní kloub, s kostmi předloktí loket.','Paže je úsek od ramene k lokti; pod loktem začíná předloktí.',[323,413],[40,480],['M319 288 Q340 272 354 298 L341 333 L326 454 L319 494 L331 534 L321 550 L278 542 Q272 528 289 510 L302 477 L316 334 Q310 308 319 288 Z'],{mirroredPaths:['M319 288 Q340 272 354 298 L341 333 L326 454 L319 494 L331 534 L321 550 L278 542 Q272 528 289 510 L302 477 L316 334 Q310 308 319 288 Z']}),
bone('kost_predlokti','Kosti předloktí','Radius et ulna','Dvě kosti umožňující i otáčení předloktí.','Mezi loktem a zápěstím: vřetenní kost na straně palce, loketní na straně malíku.','Umožňují ohnutí lokte a otočení dlaně nahoru či dolů.','Propojují pažní kost s oblastí zápěstí.','Při anatomickém postavení míří dlaně dopředu.',[264,645],[755,640],['M278 542 L309 553 L287 626 L269 701 L267 735 L229 738 L228 721 L251 658 L265 604 Z'],{mirroredPaths:['M278 542 L309 553 L287 626 L269 701 L267 735 L229 738 L228 721 L251 658 L265 604 Z']}),
bone('kost_ruka','Kosti rukou','Ossa manus','Drobné kosti pro přesný úchop.','V zápěstí, záprstí a prstech.','Umožňují jemné pohyby ruky.','Navazují na kosti předloktí a jsou ovládány svaly a šlachami.','Palec má dva články, ostatní prsty obvykle tři.',[232,787],[40,900],['M229 736 L263 735 L270 800 L265 861 L241 888 L234 865 L218 887 L210 862 L196 878 L190 858 L210 799 L181 818 L172 813 L196 769 Z'],{mirroredPaths:['M229 736 L263 735 L270 800 L265 861 L241 888 L234 865 L218 887 L210 862 L196 878 L190 858 L210 799 L181 818 L172 813 L196 769 Z']}),
bone('kost_stehenni','Stehenní kosti','Femora','Nejdelší a velmi pevné kosti těla.','Od kyčlí ke kolenům.','Nesou značnou část hmotnosti a slouží jako páky při chůzi.','Hlavice zapadá do kyčelní jamky, dolní konec se účastní kolenního kloubu.','Krček spojuje hlavici s tělem stehenní kosti.',[404,880],[755,890],['M374 710 Q384 705 399 716 L419 702 L431 723 L408 743 L403 765 L421 931 L431 990 L454 1011 Q474 1040 449 1047 L397 1048 Q379 1030 394 1007 L404 985 L389 843 L375 768 Q356 743 374 710 Z'],{mirroredPaths:['M374 710 Q384 705 399 716 L419 702 L431 723 L408 743 L403 765 L421 931 L431 990 L454 1011 Q474 1040 449 1047 L397 1048 Q379 1030 394 1007 L404 985 L389 843 L375 768 Q356 743 374 710 Z']}),
bone('kost_cesky','Čéšky','Patellae','Malé kosti na přední straně kolen.','V úponové šlaše čtyřhlavého svalu stehenního.','Zlepšují účinnost natažení kolena a chrání jeho přední část.','Pohybují se po přední ploše dolního konce stehenní kosti.','Čéška je sezamská kost: vzniká uvnitř šlachy.',[423,1030],[755,1020],['M408 1017 Q426 1004 441 1018 Q447 1034 425 1056 Q407 1045 404 1030 Z'],{mirroredPaths:['M408 1017 Q426 1004 441 1018 Q447 1034 425 1056 Q407 1045 404 1030 Z']}),
bone('kost_holenni','Holenní kosti','Tibiae','Mohutnější kosti bérců.','Na vnitřní straně bérce, mezi kolenem a kotníkem.','Přenášejí většinu zatížení z kolena na nohu.','Tvoří klouby se stehenní kostí, lýtkovou kostí a kostí hlezenní.','Holenní kost lze nahmatat na přední straně bérce.',[426,1225],[755,1210],['M401 1055 L456 1056 L455 1078 L444 1114 L437 1325 L443 1350 L456 1373 L451 1385 L409 1383 L407 1357 L418 1326 L416 1123 L399 1080 Z'],{mirroredPaths:['M401 1055 L456 1056 L455 1078 L444 1114 L437 1325 L443 1350 L456 1373 L451 1385 L409 1383 L407 1357 L418 1326 L416 1123 L399 1080 Z']}),
bone('kost_lytkova','Lýtkové kosti','Fibulae','Tenké kosti po vnějších stranách bérců.','Vedle holenních kostí.','Poskytují úpony svalům a pomáhají stabilizovat kotník.','Dolní konec tvoří vnější kotník.','Hlavní zatížení bérce přenáší holenní kost.',[396,1190],[45,1170],['M387 1065 Q399 1055 402 1072 L396 1107 L401 1242 L409 1336 L409 1384 L400 1389 L394 1373 L399 1340 L386 1141 L382 1087 Z'],{mirroredPaths:['M387 1065 Q399 1055 402 1072 L396 1107 L401 1242 L409 1336 L409 1384 L400 1389 L394 1373 L399 1340 L386 1141 L382 1087 Z']}),
bone('kost_noha','Kosti nohou','Ossa pedis','Kostěný základ chodidla a prstů.','V zánártí, nártu a prstech nohy.','Nesou tělo a umožňují odraz při chůzi.','Spolu s vazy a svaly udržují podélnou a příčnou klenbu.','Noha v anatomii znamená část pod kotníkem.',[422,1456],[755,1420],['M410 1392 L451 1391 Q461 1420 449 1440 L445 1495 L431 1515 L418 1518 L409 1508 L398 1510 L388 1500 L368 1494 L370 1469 L391 1429 Z'],{mirroredPaths:['M410 1392 L451 1391 Q461 1420 449 1440 L445 1495 L431 1515 L418 1518 L409 1508 L398 1510 L388 1500 L368 1494 L370 1469 L391 1429 Z']})
]);
