const muscle=(id,name,latin,lead,location,fn,connection,remember,anchor,label,path,extra={})=>part(id,name,latin,'svalova',lead,location,fn,connection,remember,anchor,label,[path],{mirroredPaths:[path],...extra});
add('svaly','Svaly','anatomie-svaly.webp','Povrchové kosterní svaly se stahují a táhnou za kosti prostřednictvím šlach. Vyber sval a zjisti, který pohyb pomáhá vykonat.','Přední pohled na vybrané povrchové svaly a svalové skupiny. Bělavé plochy představují zejména šlachy a vazivové povázky; svaly na zadní straně těla zde nejsou odkryté.',[
muscle('sval_kyvac','Kývač hlavy','Musculus sternocleidomastoideus','Výrazný párový sval na stranách krku.','Šikmo od oblasti za uchem k hrudní kosti a klíční kosti.','Pomáhá uklánět a otáčet hlavu; při oboustranné činnosti se podílí na ohnutí krku.','Spolupracuje s dalšími krčními svaly.','Pohyb hlavy nezajišťuje jediný sval: směr závisí na souhře více svalů.',[481,243],[45,225],'M459 177 L475 194 C481 225 493 256 502 286 L487 277 C470 242 459 205 459 177 Z'),
muscle('sval_deltovy','Deltový sval','Musculus deltoideus','Svalový kryt ramenního kloubu.','Na zevní straně ramene.','Zejména upažuje; různé části se podílejí i na předpažení a zapažení.','Upíná se na pažní kost a spolupracuje se svaly rotátorové manžety.','Ramenní kloub je velmi pohyblivý a potřebuje aktivní svalovou stabilizaci.',[340,320],[40,325],'M341 278 Q371 266 403 281 C380 316 356 344 339 360 L307 408 Q290 391 295 348 C302 315 315 289 341 278 Z'),
muscle('sval_prsni','Velký prsní sval','Musculus pectoralis major','Široký vějířovitý sval přední stěny hrudníku.','Mezi hrudní kostí, klíční kostí a horní částí pažní kosti.','Přitahuje paži k tělu a otáčí ji dovnitř.','Přenáší sílu z hrudníku na horní končetinu.','Prsní sval leží na hrudníku; srdce je hlouběji uvnitř hrudní dutiny.',[437,352],[755,305],'M401 284 L487 283 Q503 304 503 340 L501 390 Q490 423 450 422 C414 419 376 397 348 363 Z',{shortName:'Prsní sval'}),
muscle('sval_biceps','Dvojhlavý sval pažní','Musculus biceps brachii','Známý sval na přední straně paže.','Mezi ramenem a loktem.','Ohýbá loket a pomáhá otočit dlaň vzhůru.','Při pohybu spolupracuje s dalšími ohybači; proti němu působí trojhlavý sval pažní.','Sval táhne, netlačí. Opačný pohyb zajišťují jiné svaly.',[322,444],[40,450],'M337 367 Q360 369 362 402 C359 448 338 492 305 529 Q283 520 287 487 C291 445 307 394 337 367 Z',{shortName:'Biceps'}),
muscle('sval_predlokti','Ohybače předloktí','Flexores antebrachii','Skupina svalů pro ohnutí zápěstí a prstů.','Na přední, dlaňové straně předloktí.','Podílejí se na úchopu a pohybech ruky.','Jejich šlachy pokračují přes zápěstí do ruky.','Na mapě vybíráš svalovou skupinu, nikoli jeden samostatný sval.',[268,594],[40,625],'M280 508 L321 543 C328 581 299 616 273 648 L235 702 L201 695 L225 635 C229 587 248 544 280 508 Z',{shortName:'Ohybače ruky'}),
muscle('sval_primy_brisni','Přímý sval břišní','Musculus rectus abdominis','Párový sval při přední střední čáře břicha.','Od stydké kosti k oblasti dolních žeber a hrudní kosti.','Ohýbá trup a pomáhá zvyšovat nitrobřišní tlak.','S ostatními břišními svaly stabilizuje trup.','Příčné šlachové přepážky vytvářejí typické členění svalových bříšek.',[478,548],[755,525],'M466 420 L501 416 L504 589 L498 699 L479 691 C455 650 448 605 448 551 L444 471 Q442 439 466 420 Z',{shortName:'Přímý břišní'}),
muscle('sval_sikmy_brisni','Zevní šikmý sval břišní','Musculus obliquus externus abdominis','Povrchový sval po stranách břicha.','Na boční a přední stěně břicha.','Pomáhá otáčet a uklánět trup a podpírá břišní stěnu.','Spolupracuje s vnitřním šikmým a příčným břišním svalem.','Zpevnění trupu je výsledkem spolupráce břišních i zádových svalů.',[409,567],[40,550],'M395 458 L436 484 L442 555 L447 620 L473 687 L404 634 L383 608 L389 545 L379 502 Z',{shortName:'Šikmý břišní'}),
muscle('sval_pilovity','Přední pilovitý sval','Musculus serratus anterior','Sval s úpony připomínajícími pilové zuby.','Po stranách hrudníku pod podpažím.','Přitahuje lopatku k hrudníku a pomáhá ji otáčet při vzpažení.','Úzce spolupracuje s trapézovým svalem.','Lopatka se při pohybu paže také pohybuje; není pevně přilepená k hrudníku.',[393,453],[755,430],'M377 403 L403 414 L428 441 L421 451 L434 469 L426 479 L438 499 L431 514 L403 498 L392 478 L382 450 Z',{shortName:'Pilovitý sval'}),
muscle('sval_ctyrhlavy','Čtyřhlavý sval stehenní','Musculus quadriceps femoris','Velká svalová skupina na přední straně stehna.','Mezi pánví, stehenní kostí a kolenem.','Natahuje koleno; přímá hlava se podílí i na ohnutí v kyčli.','Přes čéšku a čéškový vaz přenáší tah na holenní kost.','Čtyři hlavy se spojují ve společnou šlachu.',[406,852],[40,875],'M389 642 L402 680 L429 746 L455 830 L473 899 Q480 941 456 979 L432 982 L413 929 L402 958 C369 943 351 889 350 838 C346 756 373 692 389 642 Z',{shortName:'Čtyřhlavý sval'}),
muscle('sval_krejcovsky','Krejčovský sval','Musculus sartorius','Dlouhý úzký sval šikmo přes přední stranu stehna.','Od zevní části pánve k vnitřní straně kolena.','Pomáhá ohnout kyčel a koleno a vytočit stehno zevně.','Přechází přes kyčelní i kolenní kloub.','Jeho šikmý průběh ho odlišuje od široké skupiny čtyřhlavého svalu.',[436,768],[755,795],'M389 626 L405 638 C425 700 451 758 469 820 L479 867 L471 912 L460 872 C444 796 420 732 400 683 Z',{shortName:'Krejčovský sval'}),
muscle('sval_holenni','Přední holenní sval','Musculus tibialis anterior','Sval vedle přední hrany holenní kosti.','Na přední straně bérce.','Zvedá špičku nohy a pomáhá ji stáčet dovnitř.','Při chůzi brání tomu, aby špička zachytávala o zem.','Kost je bělavá, svalové bříško červené; dole sval přechází v dlouhou šlachu.',[377,1152],[40,1150],'M375 1049 L391 1059 L395 1110 L397 1233 L403 1299 L386 1305 L376 1243 L359 1165 Q350 1106 375 1049 Z',{shortName:'Přední holenní'})
]);

add('smysly','Smyslové orgány','anatomie-smysly.webp','Smyslové receptory převádějí podněty na nervové signály. Mozek z nich vytváří vjemy. Pět ukázek představuje základní smyslové orgány; patří sem ale také vnímání rovnováhy a polohy těla.','Zvětšené řezy a pohledy nejsou ve společném měřítku. Oko, ucho, čichová oblast nosu, jazyk a kůže jsou zobrazené samostatně, nikoli ve vzájemné poloze v těle.',[
part('smysl_oko','Oko','Oculus','smyslova','Zachycuje světlo a umožňuje zrak.','V očnici lebky. V řezu je vpředu rohovka a čočka, vzadu sítnice a zrakový nerv.','Rohovka a čočka soustřeďují světlo na sítnici. Její světločivé buňky vytvářejí nervové signály.','Zrakový nerv přenáší informace k dalším centrům a do mozku.','Zornice je otvor v duhovce. Čočka je průhledný útvar za ní.',[276,243],[45,440],['M115 130 C171 45 320 32 379 112 Q411 162 411 238 L495 252 L494 345 L398 300 C372 385 301 420 206 402 C115 389 65 353 45 290 Q16 215 63 157 Z']),
part('smysl_ucho','Ucho','Auris','smyslova','Přijímá zvuk a obsahuje ústrojí rovnováhy.','Vnější ucho tvoří boltec a zvukovod. Střední a vnitřní ucho jsou v oblasti spánkové kosti.','Bubínek a sluchové kůstky přenášejí vibrace do vnitřního ucha. Vláskové buňky v hlemýždi je převádějí na nervové signály.','Sluchový nerv vede informace do mozku. Předsíň a polokruhovité kanálky pomáhají vnímat pohyb a polohu hlavy.','Hlemýžď slouží sluchu. Rovnovážné ústrojí je jinou částí vnitřního ucha.',[907,255],[750,440],['M599 61 C552 59 538 119 545 206 C548 294 558 385 588 414 Q615 433 634 408 L661 308 L767 296 L810 328 L891 402 L953 438 L998 342 L1000 189 L971 179 L881 139 L850 130 L820 205 L773 220 L664 231 L653 125 C644 76 620 57 599 61 Z']),
part('smysl_cich','Čichová oblast nosu','Regio olfactoria','smyslova','Rozpoznává pachové látky ve vdechovaném vzduchu.','V horní části nosní dutiny. Na obrázku je zvýrazněna žlutými nervovými vlákny.','Čichové receptorové buňky reagují na látky rozpuštěné ve vrstvě hlenu.','Jejich výběžky směřují do čichového bulbu; čich se významně podílí na celkovém vjemu chuti jídla.','Čichové receptory neleží na špičce nosu, ale vysoko uvnitř nosní dutiny.',[296,613],[35,930],['M279 542 Q289 520 322 530 L387 544 L480 556 L479 574 L361 564 C343 597 364 625 379 662 L216 629 C255 595 270 568 279 542 Z'],{shortName:'Čich'}),
part('smysl_jazyk','Jazyk a chuť','Lingua','smyslova','Chuťové pohárky pomáhají rozlišovat chuťové kvality.','Chuťové pohárky jsou mimo jiné v některých papilách jazyka; na obrázku je jazyk shora.','Receptory reagují na látky rozpuštěné ve slinách. Rozlišujeme sladkou, slanou, kyselou, hořkou a umami.','Chuť spolupracuje s čichem a vnímáním teploty i struktury potravy.','Neplatí mapa oddělených chuťových zón. Různé chutě vnímají oblasti jazyka s chuťovými pohárky.',[789,728],[760,930],['M655 530 Q705 495 762 503 Q807 493 861 505 C921 505 952 558 943 615 L918 735 C904 848 854 934 796 934 C735 938 684 862 665 779 L640 666 Q617 581 655 530 Z'],{shortName:'Jazyk'}),
part('smysl_kuze','Kůže a kožní čití','Cutis','smyslova','Rozhraní těla s okolím a orgán smyslového vnímání.','Pokrývá povrch těla. Řez ukazuje pokožku, škáru a podkoží.','Různé receptory a nervová zakončení umožňují vnímat dotyk, tlak, vibrace, teplotu a bolest.','Nervy vedou signály přes míchu či mozkový kmen do mozku; kůže také chrání tělo a pomáhá regulovat teplotu.','Hmat není práce jediného typu receptoru. Žlutá vlákna na obrázku představují nervy.',[538,1159],[40,1477],['M210 1027 L350 968 L704 961 L818 973 L823 1233 L814 1397 L738 1485 L210 1420 Z'],{shortName:'Kůže'})
],'Zvětšené anatomické detaily');

const heart=(id,name,latin,lead,location,fn,connection,remember,anchor,label,paths,extra={})=>part(id,name,latin,'obehova',lead,location,fn,connection,remember,anchor,label,paths,extra);
add('srdce-detail','Detail srdce','anatomie-srdce-detail.webp','Čtyři dutiny a čtyři chlopně udržují krev v jednosměrném pohybu. Pravá polovina pumpuje do plic, levá do těla. Projdi si struktury a potom cestu krve krok za krokem.','Zjednodušený řez: pravá polovina srdce je na obrázku vlevo. Modrá pouze rozlišuje krev chudší na kyslík; skutečná krev je vždy červená. Aortální chlopeň je zobrazena samostatně v detailu dole vlevo, protože ji v hlavním řezu zakrývá plicní kmen.',[
heart('srdce_dute_zily','Duté žíly','Venae cavae','Přivádějí krev z těla do pravé síně.','Horní dutá žíla ústí do síně shora, dolní zdola.','Vracejí krev s nižším obsahem kyslíku z velkého tělního oběhu.','Navazují na žilní síť těla a ústí do pravé síně.','Žíla vede krev směrem k srdci. Neurčuje ji množství kyslíku.',[290,354],[-235,300],['M246 270 Q286 244 341 262 L341 371 Q344 429 371 492 L346 498 L302 475 Q270 469 249 494 L230 538 Q242 408 246 270 Z','M200 970 L239 1000 L323 1070 L324 1189 Q273 1210 220 1191 L220 1052 Z']),
heart('srdce_prava_sin','Pravá síň','Atrium dextrum','Přijímací dutina pro krev vracející se z těla.','Vpravo v srdci; v tomto řezu nahoře vlevo.','Předává krev pravé komoře.','Přitékají sem duté žíly, krev odtéká přes trojcípou chlopeň.','Síně přijímají krev, komory ji vypuzují ze srdce.',[330,621],[-235,535],['M289 477 C328 477 350 510 386 519 Q432 533 435 585 L414 728 Q357 726 331 748 L243 782 L200 792 C181 779 196 693 203 647 L229 575 Q244 507 270 482 Z']),
heart('srdce_prava_komora','Pravá komora','Ventriculus dexter','Pumpuje krev do plicního oběhu.','Pod pravou síní; na obrázku dole vlevo.','Vypuzuje krev přes plicní chlopeň do plicního kmene.','Navazuje na pravou síň a plicní tepny.','Stěna pravé komory je tenčí než stěna levé, protože plicní oběh klade menší odpor.',[406,982],[-235,1000],['M238 801 Q282 799 336 821 L391 777 Q417 738 449 759 C480 782 487 846 499 895 L537 1027 L576 1120 Q591 1151 564 1144 C466 1120 366 1069 311 1014 C258 971 230 915 220 854 Q211 816 238 801 Z']),
heart('srdce_leva_sin','Levá síň','Atrium sinistrum','Přijímá okysličenou krev z plic.','Vlevo v srdci; v tomto řezu nahoře vpravo.','Předává krev levé komoře.','Přitékají sem plicní žíly; krev pokračuje přes dvojcípou chlopeň.','Plicní žíly nesou okysličenou krev, přesto jsou to žíly.',[728,611],[1030,530],['M663 513 C710 496 770 516 793 553 Q824 600 812 688 L805 716 Q761 731 717 719 L625 698 C611 660 623 562 645 530 Z']),
heart('srdce_leva_komora','Levá komora','Ventriculus sinister','Silná pumpa velkého tělního oběhu.','Pod levou síní; na obrázku dole vpravo.','Vypuzuje krev přes aortální chlopeň do aorty a dále do těla.','Přijímá krev z levé síně přes dvojcípou chlopeň.','Její mohutná svalová stěna vytváří tlak potřebný pro rozvod krve po těle.',[700,984],[1030,1000],['M574 755 Q596 737 623 736 L680 783 L716 811 L767 784 L807 736 C838 754 852 787 844 858 L813 1000 C798 1076 766 1131 721 1147 C674 1149 626 1099 606 1036 L568 923 C548 861 532 789 574 755 Z']),
heart('srdce_trojcipa','Trojcípá chlopeň','Valva tricuspidalis','Jednosměrná chlopeň mezi pravou síní a komorou.','V pravém síňokomorovém ústí.','Při stahu komory brání návratu krve do síně.','Její cípy jsou šlašinkami spojeny s papilárními svaly.','Šlašinky neotevírají chlopeň; pomáhají zabránit vyvrácení cípů do síně.',[324,778],[-235,745],['M230 766 Q305 739 346 735 L414 727 Q407 773 382 803 L350 825 Q313 805 287 799 L220 803 Z'],{shortName:'Trojcípá chlopeň'}),
heart('srdce_dvojcipa','Dvojcípá (mitrální) chlopeň','Valva mitralis','Jednosměrná chlopeň mezi levou síní a komorou.','V levém síňokomorovém ústí.','Brání návratu krve z levé komory do levé síně.','Dva cípy drží šlašinky a papilární svaly.','Mitrální znamená dvojcípá; oba názvy označují stejnou chlopeň.',[714,754],[1030,755],['M626 698 C675 715 735 734 806 704 Q807 750 772 777 L720 805 L678 776 Q642 759 626 728 Z'],{shortName:'Dvojcípá chlopeň'}),
heart('srdce_plicni_chlopen','Plicní chlopeň','Valva trunci pulmonalis','Poloměsíčitá chlopeň na výstupu pravé komory.','Na začátku plicního kmene.','Brání zpětnému toku z plicního kmene do komory.','Krev po průchodu pokračuje do plicních tepen.','Poloměsíčité chlopně nemají šlašinky.',[530,674],[1030,665],['M483 648 Q517 653 539 636 Q551 666 578 675 L571 692 Q548 713 524 701 Q480 702 480 672 Z']),
heart('srdce_aortalni_chlopen','Aortální chlopeň','Valva aortae','Poloměsíčitá chlopeň na výstupu levé komory.','Mezi levou komorou a aortou. Zde je zobrazen samostatný detail shora dole vlevo.','Brání zpětnému toku z aorty do levé komory.','Odděluje levou komoru od velkého tělního oběhu.','Detail není další orgán v těle: zvětšuje chlopeň skrytou v hlavním řezu za plicním kmenem.',[162,1334],[375,1400],['M163 1218 C99 1216 47 1270 44 1333 C42 1392 91 1448 158 1451 C225 1452 278 1400 281 1339 C282 1273 230 1220 163 1218 Z'],{shortName:'Aortální chlopeň',labelWidth:270}),
heart('srdce_plicni_kmen','Plicní kmen a tepny','Truncus pulmonalis','Odvádějí krev z pravé komory k plicím.','Plicní kmen se dělí na pravou a levou plicní tepnu.','Dopravují do plic krev chudší na kyslík.','Předchází jim plicní chlopeň; v plicích krev prochází kapilárami kolem sklípků.','Tepna vede krev od srdce. Plicní tepny proto mohou nést krev chudší na kyslík.',[641,419],[1030,340],['M557 334 Q607 336 629 355 C703 357 776 332 846 316 L862 322 L863 359 L813 377 L873 400 L881 416 L874 445 L853 442 L759 412 Q701 405 675 450 L613 551 L602 590 L581 667 L561 652 L539 636 L485 649 L488 600 C508 526 547 457 556 389 Z','M365 294 Q386 294 410 311 L402 375 L353 346 Z'],{shortName:'Plicní tepny'}),
heart('srdce_plicni_zily','Plicní žíly','Venae pulmonales','Vracejí okysličenou krev z plic.','Ústí do levé síně; část jejich průběhu je v řezu zakrytá.','Přivádějí krev připravenou pro velký tělní oběh.','Navazují na plicní kapiláry a ústí do levé síně.','Okysličení krve neurčuje, zda je céva tepna nebo žíla.',[856,522],[1030,445],['M784 507 L877 495 Q899 499 898 523 L891 545 L811 566 Z','M837 589 L903 585 Q920 592 918 615 L910 636 L845 635 Z','M154 489 L216 487 L210 529 L148 539 Q133 520 143 500 Z','M137 576 L190 571 L181 612 L129 632 Q115 614 124 592 Z']),
heart('srdce_aorta','Aorta','Aorta','Největší tepna těla.','Vystupuje z levé komory a vytváří oblouk nad srdcem.','Rozvádí okysličenou krev do tepen velkého oběhu.','Začíná za aortální chlopní; z oblouku odstupují tepny k hlavě a horním končetinám.','Červená barva v diagramu pomáhá sledovat okysličenou krev.',[499,309],[1030,180],['M418 132 L463 109 L490 174 Q507 196 527 176 L533 94 Q553 82 581 92 L581 164 Q586 194 601 165 L625 104 L662 109 L646 185 C701 219 731 282 734 352 L650 357 Q636 306 603 307 Q570 308 556 345 L559 407 L546 473 L523 507 L493 570 C456 540 406 487 402 440 C398 355 422 298 451 250 L451 224 Z','M666 416 L746 416 L754 480 L669 462 Z']),
heart('srdce_prepazka','Mezikomorová přepážka','Septum interventriculare','Svalová stěna mezi komorami.','Odděluje pravou a levou komoru.','Zabraňuje přímému mísení krve mezi komorami za normálních podmínek.','Je součástí srdeční svaloviny; probíhá v ní část převodního systému.','V tomto řezu je přepážka šikmá, není to svislá čára uprostřed obrázku.',[555,949],[-235,1120],['M421 725 L458 735 Q489 755 518 822 L543 745 L576 739 C549 777 548 812 560 873 C591 982 616 1094 679 1169 L698 1246 L638 1202 L596 1161 C540 1072 505 956 487 858 Q471 769 423 748 Z'],{shortName:'Přepážka'}),
heart('srdce_svalovina','Srdeční svalovina','Myocardium','Svalová vrstva, jejíž stahy pohánějí krev.','Ve stěně srdce; nejsilnější je ve stěně levé komory.','Rytmicky se stahuje a mění objem srdečních dutin.','Věnčité cévy zásobují svalovinu kyslíkem a živinami.','Srdce potřebuje vlastní krevní zásobení; nestačí krev uvnitř jeho dutin.',[853,1001],[1030,1170],['M851 744 C902 779 934 868 929 944 C922 1090 872 1250 797 1303 Q752 1334 693 1294 L646 1245 L637 1181 L606 1140 Q679 1212 743 1201 C791 1174 822 1083 837 1003 L848 906 Q866 822 851 744 Z'],{shortName:'Srdeční sval'})
],'Řez srdcem a detail chlopně');
