const rearMuscle=(id,name,latin,lead,location,fn,connection,remember,anchor,label,path,extra={})=>part(id,name,latin,'svalova',lead,location,fn,connection,remember,anchor,label,[path],{mirroredPaths:[path],mirrorX:1016,...extra});
window.ANATOMY_MODULES.push({id:'svaly-zada',topic:'svaly',view:'back',title:'Svaly zezadu',viewName:'Pohled zezadu',image:'Prirodopis/anatomie-svaly_zadni.webp',viewBox:'0 0 1024 1536',intro:'Zadní svaly pomáhají držet tělo vzpřímeně, pohybovat lopatkami, zanožit i odrazit se od země. Vyber sval nebo šlachu a porovnej jejich funkci s předním pohledem.',caption:'Pohled zezadu na vybrané povrchové svaly. Pravá strana těla je na obrázku vpravo. Bělavé části jsou převážně šlachy a vazivové povázky. Zadní stehenní svaly a natahovače předloktí jsou sdružené do skupin; hluboké svaly nejsou samostatně odkryté.',organs:[
rearMuscle('sval_trapezovy','Trapézový sval','Musculus trapezius','Rozsáhlý sval šíje a horní části zad.','Od týlní oblasti přes šíji do středu zad, směrem k lopatkám a klíčním kostem.','Jeho části zvedají, přitahují a spouštějí lopatku; společně pomáhají jejímu otáčení při zvedání paže.','Spolupracuje s předním pilovitým svalem a dalšími svaly lopatky.','Jednotlivé části trapézového svalu mají odlišný směr vláken a mohou působit různě.',[465,290],[40,205],'M462 136 L496 132 L502 199 L503 447 Q477 418 458 364 L425 272 Q397 261 370 246 L451 197 Z',{shortName:'Trapézový sval'}),
rearMuscle('sval_deltovy','Deltový sval','Musculus deltoideus','Zadní část svalového krytu ramene.','Na zevní a zadní straně ramenního kloubu.','Zadní část pomáhá zapažit a zevně otáčet paži; celý sval se podílí také na upažení.','Spolupracuje s rotátorovou manžetou a svaly pohybujícími lopatkou.','Stejný deltový sval je vidět také zepředu; jednotlivé části mají různé úkoly.',[330,300],[45,310],'M340 254 Q364 250 393 264 L383 284 Q366 316 345 330 L288 371 C278 335 291 282 320 263 Z',{shortName:'Deltový sval'}),
rearMuscle('sval_podhrebenovy','Podhřebenový sval','Musculus infraspinatus','Jeden ze svalů rotátorové manžety.','Na zadní ploše lopatky pod jejím hřebenem.','Zevně otáčí paži a pomáhá stabilizovat hlavici pažní kosti v ramenní jamce.','Je součástí skupiny svalů, které aktivně stabilizují ramenní kloub.','Název popisuje polohu pod hřebenem lopatky, nikoli pod páteří.',[398,332],[760,285],'M393 280 L418 279 L427 312 L435 361 Q396 375 358 342 L348 328 Q377 307 393 280 Z',{shortName:'Podhřebenový'}),
rearMuscle('sval_siroky_zadovy','Široký sval zádový','Musculus latissimus dorsi','Široký sval po stranách střední a dolní části zad.','Od dolní oblasti zad a pánve směrem k horní části pažní kosti.','Pomáhá připažit, zapažit a otáčet paži dovnitř.','Spolu s dalšími svaly se uplatňuje při přitahování těla k opoře.','Široká bělavá plocha uprostřed dolních zad je vazivová povázka, ne další svalové bříško.',[411,441],[760,420],'M356 359 Q394 373 453 367 L474 414 L490 451 L482 477 L433 555 L417 565 L386 558 Q383 517 375 472 L363 424 Z',{shortName:'Široký zádový'}),
rearMuscle('sval_triceps','Trojhlavý sval pažní','Musculus triceps brachii','Hlavní natahovač lokte.','Na zadní straně paže od ramene k lokti.','Natahuje loket; dlouhá hlava se podílí také na pohybu paže v rameni.','Při řízení pohybu spolupracuje s ohybači lokte, například bicepsem.','Biceps loket převážně ohýbá, triceps jej natahuje. Oba svaly mohou spolupracovat i při stabilizaci.',[315,407],[40,435],'M329 342 L348 330 Q361 362 355 402 C347 443 328 478 306 497 L289 473 L280 444 Q281 386 307 357 Z',{shortName:'Triceps'}),
rearMuscle('sval_natahovace','Natahovače předloktí','Extensores antebrachii','Svalová skupina pro natažení zápěstí a prstů.','Na zadní straně předloktí; dlouhé šlachy pokračují přes hřbet ruky.','Umožňuje otevřít ruku a zvedat hřbet ruky směrem k předloktí.','Působí v souhře s ohybači předloktí a drobnými svaly ruky.','Na mapě je zvýrazněna skupina svalů. Bílé provazce směrem k prstům jsou jejich šlachy.',[259,575],[40,595],'M271 478 L286 491 L276 524 L304 534 C292 572 263 612 237 649 L216 682 L192 680 L204 633 L215 574 Q230 519 271 478 Z',{shortName:'Natahovače ruky'}),
rearMuscle('sval_stredni_hyzdovy','Střední hýžďový sval','Musculus gluteus medius','Důležitý stabilizátor pánve při chůzi.','Na zevní straně pánve, zčásti překrytý velkým hýžďovým svalem.','Pomáhá unožit a udržet pánev při stoji na jedné noze.','Spolupracuje s dalšími svaly kolem kyčelního kloubu.','Na zadním pohledu je vidět jen odkrytá horní a zevní část svalu.',[388,607],[760,570],'M387 578 Q407 572 435 594 L415 603 L392 624 L375 656 L366 680 C363 637 370 596 387 578 Z',{shortName:'Střední hýžďový'}),
rearMuscle('sval_velky_hyzdovy','Velký hýžďový sval','Musculus gluteus maximus','Silný sval, který pomáhá narovnat kyčel.','Na zadní straně pánve a horní části stehna.','Zanožuje a zevně otáčí stehno; výrazně se uplatňuje při vstávání a chůzi do schodů.','Spolupracuje se zadními stehenními svaly a stabilizátory pánve.','Při vstávání pomáhá přesunout trup z předklonu do vzpřímené polohy.',[439,679],[40,735],'M421 602 C449 609 480 632 496 657 Q505 696 496 730 C474 752 433 760 395 774 L358 800 L364 748 C369 684 383 631 421 602 Z',{shortName:'Velký hýžďový'}),
rearMuscle('sval_hamstringy','Zadní stehenní svaly','Musculi ischiocrurales','Skupina označovaná také jako hamstringy.','Na zadní straně stehna mezi pánví a kolenem.','Ohýbá koleno; většina skupiny se také podílí na zanožení.','Patří sem dvojhlavý sval stehenní, sval pološlašitý a poloblanitý.','Přední čtyřhlavý sval koleno natahuje, zadní stehenní svaly ho ohýbají.',[418,877],[760,860],'M395 777 L447 759 L490 742 C496 795 478 873 473 919 L451 1008 L436 1012 L416 974 L401 1000 L373 1033 L368 989 L359 961 C342 903 341 846 349 808 Z',{shortName:'Zadní stehenní'}),
rearMuscle('sval_lytkovy','Dvojhlavý sval lýtkový','Musculus gastrocnemius','Dvě výrazná svalová bříška na zadní straně lýtka.','Pod kolenem na povrchu zadní strany bérce.','Pomáhá zvednout patu a postavit se na špičku; podílí se také na ohnutí kolena.','Spolu s hlubším šikmým svalem lýtkovým tvoří trojhlavý sval lýtkový.','Jeho dvě hlavy se dole sbíhají do společného šlachového úponu.',[383,1122],[40,1100],'M385 1019 Q402 1013 414 1030 Q427 1015 440 1024 C454 1062 469 1112 463 1158 Q461 1190 439 1210 L414 1193 L399 1182 L384 1198 C355 1185 341 1144 348 1104 Q356 1056 385 1019 Z',{shortName:'Lýtkový sval'}),
rearMuscle('slacha_achillova','Achillova šlacha','Tendo calcaneus','Pevná šlacha přenášející tah lýtkových svalů na patu.','Na zadní straně dolního bérce nad patou.','Přenáší svalovou sílu při odrazu, chůzi a běhu.','Spojuje trojhlavý sval lýtkový s patní kostí.','Šlacha se sama aktivně nestahuje. Sílu vytvářejí svalová vlákna nad ní.',[407,1303],[755,1290],'M393 1190 L409 1203 L430 1203 L425 1248 L420 1325 L425 1361 L415 1390 L392 1390 L388 1360 L394 1324 L393 1265 L385 1227 Z',{shortName:'Achillova šlacha'})
]});
