add('nervova','Nervová soustava','anatomie-nervova.webp','Mozek a mícha tvoří centrální nervovou soustavu. Obvodové nervy je propojují s tělem: přivádějí informace z receptorů a vedou pokyny ke svalům a žlázám.','Pohled zezadu s průhledem do těla. Nervy jsou pro přehlednost zesílené a barevně odlišené; žlutá není jejich skutečná barva. Větvení je schematické. Mícha nepokračuje až do pánve: pod jejím koncem sestupují nervové kořeny. Autonomní nervy a všechny drobné větve zde nejsou samostatně znázorněné.',[
nerve('nerv_velky_mozek','Koncový mozek','Telencephalon','Dvě mozkové hemisféry se zvrásněným povrchem.','V horní a největší části mozku uvnitř lebky.','Podílí se na vědomém vnímání, myšlení, paměti, řeči a řízení volních pohybů.','Jednotlivé oblasti spolupracují mezi sebou i s ostatními částmi mozku.','Mozek funguje jako propojená síť; složité úkoly nezajišťuje jediný bod.',[480,65],[35,40],['M448 65 C456 8 554 5 570 61 L573 96 L558 110 Q535 109 510 98 Q474 113 450 105 Z'],{shortName:'Koncový mozek'}),
nerve('nerv_mozecek','Mozeček','Cerebellum','Členitá část mozku pod zadní částí hemisfér.','V zadní dolní části lebky, za mozkovým kmenem.','Pomáhá koordinovat přesnost pohybů, rovnováhu a motorické učení.','Zpracovává informace o poloze těla a porovnává plánovaný pohyb s provedením.','Mozeček pomáhá pohyb doladit; není jediným centrem rovnováhy.',[477,117],[755,115],['M460 111 Q480 104 506 103 L507 127 L496 141 Q466 141 460 111 Z','M515 103 Q544 108 559 112 Q556 137 530 141 L516 128 Z']),
nerve('nerv_kmen','Mozkový kmen','Truncus encephali','Spojení mozku s míchou a místo důležitých řídicích center.','Na spodině mozku, před mozečkem; ilustrace jej odkrývá průhledem.','Podílí se na řízení dýchání, oběhu, bdělosti a dalších základních funkcí.','Procházejí jím dráhy mezi mozkem a míchou; souvisejí s ním mnohé hlavové nervy.','Mozkový kmen tvoří střední mozek, most a prodloužená mícha.',[510,140],[35,170],['M501 124 Q511 118 520 127 L518 159 L504 159 Z']),
nerve('nerv_micha','Mícha','Medulla spinalis','Část centrální nervové soustavy chráněná páteří.','V páteřním kanálu; u dospělého obvykle končí přibližně u prvního až druhého bederního obratle.','Vede informace mezi mozkem a tělem a podílí se na míšních reflexech.','Navazuje na prodlouženou míchu; připojují se k ní kořeny míšních nervů.','Mícha není páteř: páteř je kostěný obal, mícha je nervová tkáň.',[510,380],[755,350],['M503 160 L518 160 L518 470 L514 516 L510 534 L503 498 Z']),
nerve('nerv_pazni_pleten','Pažní pleteně','Plexus brachiales','Sítě nervových vláken směřujících do horních končetin.','Po stranách dolního krku a směrem do podpaží.','Rozdělují nervová vlákna do nervů zásobujících ramena, paže, předloktí a ruce.','Vznikají převážně z předních větví míšních nervů C5 až T1.','Pleteň je propojení nervových větví, nikoli nový úsek míchy.',[428,259],[35,265],['M487 200 L477 236 L425 276 L366 312 L350 298 L409 255 Z'],{mirroredPaths:['M487 200 L477 236 L425 276 L366 312 L350 298 L409 255 Z']}),
nerve('nerv_horni','Nervy horních končetin','Nervi membri superioris','Vybrané obvodové nervy paží, předloktí a rukou.','Od podpaží přes horní končetiny až do prstů.','Vedou pokyny ke svalům a přivádějí informace o dotyku, bolesti či poloze končetiny.','Navazují na pažní pleteň; patří sem například nerv středový, loketní a vřetenní.','Na mapě vybíráš skupinu nervů. V jednom nervu mohou vést vlákna různé druhy informací.',[297,525],[35,465],['M351 314 L391 311 L352 460 L326 529 L309 584 L274 645 L229 705 L219 777 L196 833 L180 828 L200 764 L170 841 L147 850 L167 778 L131 839 L122 827 L153 756 L118 774 L112 760 L180 702 L234 614 L263 535 L295 468 L313 390 Z'],{mirroredPaths:['M351 314 L391 311 L352 460 L326 529 L309 584 L274 645 L229 705 L219 777 L196 833 L180 828 L200 764 L170 841 L147 850 L167 778 L131 839 L122 827 L153 756 L118 774 L112 760 L180 702 L234 614 L263 535 L295 468 L313 390 Z'],shortName:'Nervy paží a rukou'}),
nerve('nerv_mezizeberni','Mezižeberní nervy','Nervi intercostales','Nervy probíhající mezi sousedními žebry.','Ve stěně hrudníku; dolní pokračují také do břišní stěny.','Zajišťují nervové zásobení části svalů a kůže hrudní a břišní stěny.','Jsou pokračováním předních větví hrudních míšních nervů.','Oblouky na obrázku ukazují jejich průběh; nejde o krevní cévy.',[445,389],[755,460],['M493 278 L493 483 L463 508 L432 541 L399 532 L391 489 L401 426 L424 363 L442 302 Z'],{mirroredPaths:['M493 278 L493 483 L463 508 L432 541 L399 532 L391 489 L401 426 L424 363 L442 302 Z']}),
nerve('nerv_cauda','Koňský ohon','Cauda equina','Svazek sestupujících míšních nervových kořenů.','V páteřním kanálu pod dolním koncem míchy.','Kořeny vedou k níže uloženým výstupům z páteřního kanálu.','Navazují na dolní úseky míchy a podílejí se na zásobení dolní části těla.','Koňský ohon už není mícha. Tvoří ho nervové kořeny připomínající koňský ocas.',[511,583],[755,590],['M505 534 L518 534 L532 620 L531 682 L491 682 L491 620 Z']),
nerve('nerv_krizova','Křížové pleteně','Plexus sacrales','Nervové pleteně zásobující velkou část dolních končetin a pánevní oblast.','Uvnitř pánve před křížovou kostí; zde jsou odkryté průhledem.','Rozdělují vlákna do nervů pánve a dolních končetin.','Navazují na bederní a křížové míšní nervy; vystupuje z nich sedací nerv.','Pleteně jsou párové. Zde je zvýrazněna schematicky zobrazená oblast jejich větvení.',[448,674],[35,650],['M483 623 L492 651 L468 679 L442 695 L427 724 L412 720 L416 685 L450 656 Z'],{mirroredPaths:['M483 623 L492 651 L468 679 L442 695 L427 724 L412 720 L416 685 L450 656 Z'],shortName:'Křížové pleteně'}),
nerve('nerv_sedaci','Sedací nervy','Nervi ischiadici','Mohutné nervy na zadní straně stehen.','Od křížové pleteně pod hýžďovými svaly směrem ke kolenu.','Zajišťují nervové spojení s částí stehna a prostřednictvím větví s většinou bérce a nohy.','Dělí se na nerv holenní a společný lýtkový.','Sedací nerv je obvodový nerv, nikoli prodloužení míchy do nohy.',[430,871],[755,855],['M416 725 L431 725 L446 788 L442 881 L435 947 L423 993 L410 990 L423 935 L428 869 L431 789 Z'],{mirroredPaths:['M416 725 L431 725 L446 788 L442 881 L435 947 L423 993 L410 990 L423 935 L428 869 L431 789 Z']}),
nerve('nerv_dolni','Nervy bérců a nohou','Nervi cruris et pedis','Větve nervů pokračující pod kolena až k prstům nohou.','V bércích, kolem kotníků a v chodidlech.','Ovládají příslušné svaly a vedou čití z částí bérce a nohy.','Patří sem větve holenního a společného lýtkového nervu; vnitřní stranu bérce zásobuje také větev stehenního nervu.','Nervy umožňují vnímat došlap a spolu se svaly upravovat polohu nohy.',[403,1173],[35,1140],['M407 995 L436 997 L454 1090 L445 1196 L425 1326 L437 1427 L426 1452 L382 1449 L330 1431 L328 1413 L373 1380 L385 1332 L369 1225 L350 1115 L355 1064 Z'],{mirroredPaths:['M407 995 L436 997 L454 1090 L445 1196 L425 1326 L437 1427 L426 1452 L382 1449 L330 1431 L328 1413 L373 1380 L385 1332 L369 1225 L350 1115 L355 1064 Z'],shortName:'Nervy bérců a nohou',labelWidth:270})
],'Pohled zezadu · průhled');
